&reftitle.parameters;


  other


    The value to compare the current instance to.

  &reftitle.examples;

   Ds\Key::equals example


<?php
class User implements \Ds\Key
{
    public function __construct(private string $email) {}

    public function hash(): mixed
    {
        return $this->email;
    }

    public function equals(mixed $other): bool
    {
        return $other instanceof self && $this->email === $other->email;
    }
}

$set = new \Ds\Set();
$set->add(new User("a@example.com"));
$set->add(new User("a@example.com"));

var_dump(count($set));
?>


